    @Test
    void exemplo4_retiradaLojaComLeve3Pague2Cartao3xPrata() {
        ResumoRequest request = new ResumoRequest(
                List.of(item("Meia", 19.90, 7, 0.10), item("Camiseta", 79.90, 2, 0.30)),
                "RETIRADA_LOJA", "LEVE3PAGUE2", "CARTAO", 3, "PRATA", "SUL"
